let statement =
  `!r:int32.
     (&22:int) < ival r
     ==>
     (--(&2147483648:int) <= (&42:int) /\
      (&42:int) <= (&2147483647:int)) /\
     (!o1:int32.
        ival o1 = (&42:int)
        ==>
        (--(&2147483648:int) <= ival o1 + ival o1 /\
         ival o1 + ival o1 <= (&2147483647:int)) /\
        (!o2:int32.
           ival o2 = ival o1 + ival o1
           ==> ival o2 <= (&42:int)))`;;

(*
  Statement-only formalization of NTP4VC corpus artifact
  pearl/queens_bv_Bits_belowqtvc: a 32-bit verification condition identifying
  the low-bit mask below a bounded word with its finite integer-set model and
  preserving that model in the result record. This file contains no proof.
*)

let queens_bv_output = open_out "/dev/null";;
let queens_bv_formatter = Format.formatter_of_out_channel queens_bv_output;;
let queens_bv_previous_loader = !Hol_loader.file_loader;;
Hol_loader.file_loader :=
  (fun path -> Toploop.use_file queens_bv_formatter path);;
let queens_bv_words_loaded =
  Toploop.use_file queens_bv_formatter "Library/words.ml";;
Hol_loader.file_loader := queens_bv_previous_loader;;
Format.pp_print_flush queens_bv_formatter ();;
close_out queens_bv_output;;
if not queens_bv_words_loaded then
  failwith "failed to load Library/words.ml";;

let queens_bv_nat_of_int = new_definition
  `queens_bv_nat_of_int (z:int) =
     if (&0:int) <= z then num_of_int z else 0`;;

let queens_bv_interval = new_definition
  `queens_bv_interval (lower:int) (upper:int) =
     \i:int. lower <= i /\ i < upper`;;

let statement =
  `!bv:A->int32. !mdl:A->int->bool.
     ((!i:int. !self:A.
         (((&0:int) <= i /\ i < (&32:int)) /\
          bit (queens_bv_nat_of_int i) (bv self) <=>
          i IN mdl self)) /\
      (!a b:A.
         bv a = bv b /\ mdl a = mdl b
         ==> a = b))
     ==>
     !n:int32.
       word_ule n (word 32:int32)
       ==>
       let o1 =
         queens_bv_interval (&0:int) (&(val n):int) in
       let o2 =
         word_not
           (word_shl (word 4294967295:int32) (val n)) in
       (!i:int.
          (((&0:int) <= i /\ i < (&32:int)) /\
           bit (queens_bv_nat_of_int i) o2 <=>
           i IN o1)) /\
       (!result:A.
          bv result = o2 /\ mdl result = o1
          ==>
          mdl result =
          queens_bv_interval (&0:int) (&(val n):int))`;;

(*
  Statement-only formalization of NTP4VC corpus artifact
  pearl/queens_bv_Bits_rightmost_bit_trickqtvc: a 32-bit verification
  condition stating that a nonzero word AND its two's-complement negation has
  exactly the least set bit in its finite integer-set model. This file contains
  no proof.
*)

let queens_bv_rightmost_output = open_out "/dev/null";;
let queens_bv_rightmost_formatter =
  Format.formatter_of_out_channel queens_bv_rightmost_output;;
let queens_bv_rightmost_previous_loader = !Hol_loader.file_loader;;
Hol_loader.file_loader :=
  (fun path -> Toploop.use_file queens_bv_rightmost_formatter path);;
let queens_bv_rightmost_words_loaded =
  Toploop.use_file queens_bv_rightmost_formatter "Library/words.ml";;
Hol_loader.file_loader := queens_bv_rightmost_previous_loader;;
Format.pp_print_flush queens_bv_rightmost_formatter ();;
close_out queens_bv_rightmost_output;;
if not queens_bv_rightmost_words_loaded then
  failwith "failed to load Library/words.ml";;

let queens_bv_rightmost_nat_of_int = new_definition
  `queens_bv_rightmost_nat_of_int (z:int) =
     if (&0:int) <= z then num_of_int z else 0`;;

let queens_bv_rightmost_minimum = new_definition
  `queens_bv_rightmost_minimum (s:int->bool) =
     @m:int. m IN s /\ (!j:int. j IN s ==> m <= j)`;;

let statement =
  `!bv:A->int32. !mdl:A->int->bool.
     ((!i:int. !self:A.
         (((&0:int) <= i /\ i < (&32:int)) /\
          bit (queens_bv_rightmost_nat_of_int i) (bv self) <=>
          i IN mdl self)) /\
      (!a b:A.
         bv a = bv b /\ mdl a = mdl b
         ==> a = b))
     ==>
     !a:A.
       ~(mdl a = {})
       ==>
       let res =
         word_and (bv a) (word_neg (bv a)) in
       let minimum =
         queens_bv_rightmost_minimum (mdl a) in
       let o1 =
         minimum INSERT ({}:int->bool) in
       (!i:int.
          (((&0:int) <= i /\ i < (&32:int)) /\
           bit (queens_bv_rightmost_nat_of_int i) res <=>
           i IN o1)) /\
       (!result:A.
          bv result = res /\ mdl result = o1
          ==>
          mdl result =
          minimum INSERT ({}:int->bool))`;;

:: Statement-only formalization of NTP4VC corpus artifact pearl/vacid_0_red_black_trees_Vacid0_lookupqtvc: the lookup verification condition for an integer-keyed red-black-tree map with a default value, relating the tree invariant, key-value membership, key absence, and returned values. This file contains no proof.

environ

 vocabularies NUMBERS, XBOOLE_0, SUBSET_1, FUNCT_1, FUNCT_2, PARTFUN1,
      FINSEQ_1, FINSET_1, RELAT_1, TARSKI, ZFMISC_1, XTUPLE_0, TREES_1,
      TREES_2, TREES_3, TREES_4, DTCONSTR, BINTREE1, MARGREL1, XBOOLEAN,
      INT_1, CARD_1, ARYTM_1, ARYTM_3, XXREAL_0, XREAL_0, REAL_1, NAT_1,
      VALUED_0, VALUED_1, ORDINAL1, ORDINAL4, MCART_1, ABSRED_0;
 notations TARSKI, XBOOLE_0, ZFMISC_1, XTUPLE_0, SUBSET_1, ORDINAL1,
      CARD_1, NUMBERS, XCMPLX_0, XREAL_0, REAL_1, INT_1, NAT_1, XXREAL_0,
      MCART_1, RELAT_1, FUNCT_1, RELSET_1, PARTFUN1, FUNCT_2, FINSEQ_1,
      FINSET_1, TREES_1, TREES_2, TREES_3, TREES_4, DTCONSTR, BINTREE1,
      MARGREL1;
 constructors FUNCT_1, RELSET_1, PARTFUN1, FUNCT_2, CARD_1, REAL_1, INT_1,
      XXREAL_0, ZFMISC_1, MCART_1, NAT_1, FINSEQOP, DTCONSTR, BINTREE1,
      MARGREL1, XTUPLE_0;
 registrations XBOOLE_0, SUBSET_1, RELAT_1, FUNCT_1, RELSET_1, FUNCT_2,
      NUMBERS, CARD_1, XXREAL_0, MEMBERED, VALUED_0, VALUED_1, XCMPLX_0,
      XREAL_0, ORDINAL1, INT_1, NAT_1, FINSEQ_1, TREES_1, TREES_2, TREES_3,
      TREES_4, DTCONSTR, FINSET_1, BINTREE1, MARGREL1;
 requirements REAL, NUMERALS, SUBSET, BOOLE, ARITHM;

begin

definition
  let T be DecoratedTree;
  pred T <== means
    T is finite & T is binary &
    for p being Node of T holds
      (p in Leaves dom T iff T.p = {}) &
      (not p in Leaves dom T implies
        p^<*0*> in dom T & p^<*1*> in dom T &
        ex c being Element of BOOLEAN, k,v being Integer st
          T.p = [c,[k,v]]);
end;

definition
  let T be DecoratedTree;
  let k,v be Integer;
  pred T =01=> k,v means
    ex p being Node of T, c being Element of BOOLEAN st
      not p in Leaves dom T & T.p = [c,[k,v]];
end;

definition
  let T be DecoratedTree;
  let x be Integer;
  pred T =*=> x means
    for k,v being Integer st T =01=> k,v holds k < x;
  pred T =+=> x means
    for k,v being Integer st T =01=> k,v holds x < k;
end;

definition
  let T be DecoratedTree;
  pred T <=01= means
    T <== &
    for p being Node of T, c being Element of BOOLEAN,
        k,v being Integer st
      not p in Leaves dom T & T.p = [c,[k,v]]
    holds
      (T|(p^<*0*>)) =*=> k & (T|(p^<*1*>)) =+=> k;
end;

definition
  let T be DecoratedTree;
  pred T <=*= means
    T <== &
    ({} in Leaves dom T or
      ex k,v being Integer st T.{} = [TRUE,[k,v]]);
end;

definition
  let T be finite binary DecoratedTree;
  let n be Integer;
  pred T <=+= n means
    T <== &
    (for p being Node of T, k,v being Integer st
      not p in Leaves dom T & T.p = [FALSE,[k,v]]
     holds
      (T|(p^<*0*>)) <=*= & (T|(p^<*1*>)) <=*=) &
    for p being Node of T st p in Leaves dom T holds
      n = card {q where q is Node of T:
        q is_a_prefix_of p &
        not q in Leaves dom T &
        ex k,v being Integer st T.q = [TRUE,[k,v]]};
end;

::$P-
theorem
  for m,k being Integer,
      T being finite binary DecoratedTree st
    T <=01= & ex n being Integer st T <=+= n
  holds
    T <=01= &
    (for result being Integer holds
      (T =01=> k,result or
        ((for v being Integer holds not T =01=> k,v) &
          result = m))
      implies
        T =01=> k,result or
        (result = m &
          for v being Integer holds not T =01=> k,v))
proof
end;
::$P+

