    (for T2 being finite binary DecoratedTree holds
      ((T2 <=01= & ex n being Integer st T2 <=+= n) &
       (for k1,v1 being Integer holds
         (T2 =01=> k1,v1 or
           (v1 = m &
             for w being Integer holds not T2 =01=> k1,w))
         iff
         ((k1 = k & v1 = m) or
          (k1 <> k &
            (T1 =01=> k1,v1 or
              (v1 = m &
                for w being Integer holds not T1 =01=> k1,w))))))
      implies
      ((T2 <=01= & ex n being Integer st T2 <=+= n) &
       (for k1,v1 being Integer holds
         (T2 =01=> k1,v1 or
           (v1 = m &
             for w being Integer holds not T2 =01=> k1,w))
         iff
         ((k1 = k & v1 = m) or
          (k1 <> k &
            (T1 =01=> k1,v1 or
